  </div>\n            </div>\n        </div>\n\n        <div class="fiesta-card">\n            <div class="fiesta-header">\n                <i class="fas fa-map-marker-alt" style="color: var(--primary); margin-right: 10px;"></i>\n                <h3>CAÑADA DE LA CRUZ</h3>\n            </div>\n            <div class="fiesta-body">\n                <div class="event-item">\n                    <div class="event-date"><i class="far fa-calendar-alt"></i> 15 DE AGOSTO</div>\n                    <div class="event-name">LA ASUNCIÓN</div>\n                </div>\n            </div>\n        </div>\n\n        <div class="fiesta-card">\n            <div class="fiesta-header">\n                <i class="fas fa-map-marker-alt" style="color: var(--primary); margin-right: 10px;"></i>\n                <h3>EL SABINAR</h3>\n            </div>\n            <div class="fiesta-body">\n                <div class="event-item">\n                    <div class="event-date"><i class="far fa-calendar-alt"></i> 24 DE AGOSTO</div>\n                    <div class="event-name">SAN BARTOLOMÉ</div>\n                </div>\n            </div>\n        </div>\n\n        <div class="fiesta-card">\n            <div class="fiesta-header">\n                <i class="fas fa-map-marker-alt" style="color: var(--primary); margin-right: 10px;"></i>\n                <h3>ROGATIVA</h3>\n            </div>\n            <div class="fiesta-body">\n                <div class="event-item">\n                    <div class="event-date"><i class="far fa-calendar-alt"></i> DOMINGO PRÓXIMO A LA ASUNCIÓN</div>\n                    <div class="event-name">ROMERÍA VIRGEN DE LA ROGATIVA</div>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</div>' WHERE `id` = 163;\n
